+/* Pins: a dot for a lead, a star for a sale, a red hand for do-not-knock, a small grey dot for a door knock. */
+.dd-pin { background: none; border: 0; }
+.dd-pin span { display: block; width: 100%; height: 100%; background: var(--c, #5f6b7a); }
+.dd-pin-leads span { border-radius: 50%; border: 3px solid #fff; box-shadow: 0 0 0 1px rgb(0 0 0 / .4); }
+.dd-pin-sales span { clip-path: polygon(50% 0, 61% 35%, 98% 35%, 68% 57%, 79% 91%, 50% 70%, 21% 91%, 32% 57%, 2% 35%, 39% 35%); }
+.dd-pin-dnk span { background: #b42318; color: #fff; border-radius: 6px; border: 2px solid #fff; box-shadow: 0 0 0 1px rgb(0 0 0 / .4); font-size: 12px; line-height: 16px; text-align: center; }
+.dd-pin-checkins span { border-radius: 50%; background: #5f6b7a; opacity: .75; border: 2px solid #fff; }
+
+/* admin.css styles every <label> and <input> for forms. Keep that out of Leaflet's own controls. */
+.leaflet-container label { display: block; gap: 0; font-size: 13px; color: #1b1f24; }
+.leaflet-container input[type="checkbox"], .leaflet-container input[type="radio"] { width: auto; padding: 0; }
+.leaflet-control-layers-expanded { padding: 6px 10px; }
+
+.dd-popup { display: grid; gap: 2px; font: 14px/1.35 system-ui, -apple-system, "Segoe UI", sans-serif; color: #1b1f24; }
+.dd-popup-title { font-weight: 700; }
+.dd-popup button { margin-top: 6px; }
+
+.dd-legend { background: rgb(255 255 255 / .92); color: #1b1f24; padding: 6px 10px; border-radius: 8px; font: 13px/1.6 system-ui, sans-serif; box-shadow: 0 1px 4px rgb(0 0 0 / .3); }
+.dd-legend-sample { display: inline-block; width: 14px; height: 14px; vertical-align: -2px; margin-right: 6px; }
+.dd-legend-sample.dd-pin-dnk span { font-size: 9px; line-height: 10px; }
+
+.dd-locate { background: #fff; color: #1b1f24; border: 2px solid rgb(0 0 0 / .25); border-radius: 6px; padding: 8px 12px; font: 600 14px system-ui, sans-serif; cursor: pointer; }
+.map-note { margin: 8px 0 0; min-height: 1.4em; }
+
+/* Phone map page: the map fills the screen under a slim top bar. */
+.map-page { display: grid; grid-template-rows: auto 1fr auto; height: 100dvh; }
+.map-page .topbar { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 10px 16px; background: var(--panel); border-bottom: 1px solid var(--line); }
+.map-page .topbar strong { font-size: 1.05rem; }
+.map-page .map { height: 100%; border: 0; border-radius: 0; }
+.map-page .map-note { padding: 6px 16px; background: var(--panel); border-top: 1px solid var(--line); margin: 0; }
